contract MockEulerProtocol {
    using SafeERC20 for IERC20;

    function requestUnderlyingFromRelayer(
        address underlying,
        uint256 amount,
        address relayer
    ) public {
        IERC20(underlying).safeTransferFrom(relayer, (address(this)), amount);
